UPDATE study_task
SET status = #{task.status},
    completed_at = CASE WHEN #{task.status} = 'COMPLETED' THEN NOW() ELSE NULL END,
    version = version + 1,
    update_time = NOW()
WHERE id = #{task.id}
  AND user_id = #{task.userId}
  AND version = #{expectedVersion}
  AND deleted = 0
